import{_ as i,l as R,o as t,c as n,v as e,p as l,x as r,d as A,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"HAR 已实现波动","description":"","frontmatter":{"title":"HAR 已实现波动","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/har-rv.md","filePath":"quant/har-rv.md","lastUpdated":1789023840000}'),p={name:"quant/har-rv.md"};function h(V,a,_,c,E,H){const o=R("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="har-已实现波动" tabindex="-1">HAR 已实现波动 <a class="header-anchor" href="#har-已实现波动" aria-label="Permalink to &quot;HAR 已实现波动&quot;">​</a></h1><div class="epigraph"><p>把已实现波动写成日、周、月三个滞后的线性组合，就能用短记忆的异质成分逼近长记忆，而不必估计分整阶数。</p><footer>—— Corsi, A Simple Approximate Long-Memory Model of Realized Volatility, Journal of Financial Econometrics 2009</footer></div><p><a href="/quant/unit-root">上一课</a>给出 \\(\\rho=1\\) 时估计量的非标准分布，并警告 I(1) 水平回归会伪回归；对数价格当 I(1)、收益当 I(0) 是工作默认，波动的阶数要单独检查。缺口是已实现波动的自相关拖得很长：FIGARCH 或 ARFIMA 能描述，却难估计、难约束为正。Corsi 用日、周、月 RV 的线性组合近似长记忆，避免估计分整阶数。本课问的是 <strong>RV 的条件均值</strong>如何预报明天，不是噪声下如何构造 RV。不重推 ADF 临界值。后课已实现核默认已经把预测对象与估计对象分开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记 \\(RV_t\\) 为第 \\(t\\) 日积分波动的估计（朴素五分钟、TSRV 或核）。经验上 \\(\\mathrm{Corr}(RV_t,RV_{t-h})\\) 随 \\(h\\) 缓慢下降，单滞后 AR(1) 不够，高阶 AR 参数多且不稳定。分整 \\(d\\in(0,0.5)\\) 能产生双曲线衰减，但对短样本的 \\(d\\) 估得很噪，预测还要保证正性。问题是：用一个稳定、几乎无需非线性优化的线性模型，捕捉 RV 的多尺度持续，并给出可解释的日/周/月载荷。</p><p>Corsi 的 HAR-RV 写为</p> \\[RV_{t+1}=c+\\beta_d RV_t+\\beta_w RV_{t-5:t}+\\beta_m RV_{t-22:t}+\\varepsilon_{t+1}, \\]<p>其中 \\(RV_{t-k:t}\\) 是过去 \\(k\\) 日 RV 的平均（周用 5 个交易日，月用 22）。这是对 RV 的有约束 AR(22)：远端滞后被绑成两段均值。约束换来的是稳健，以及与异质期限的对应。</p><h3 id="对象是-rv-的预测-不是期权隐含的风险中性方差" tabindex="-1">对象是 RV 的预测，不是期权隐含的风险中性方差 <a class="header-anchor" href="#对象是-rv-的预测-不是期权隐含的风险中性方差" aria-label="Permalink to &quot;对象是 RV 的预测，不是期权隐含的风险中性方差&quot;">​</a></h3><p>HAR 的左边是已实现测度，损失函数通常是 MSE 或 QLIKE（对波动预测更合适）。它不包含风险溢价，故不能直接当期权隐含波动的无偏预测；隐含减已实现的差距是方差风险溢价，留给后续篇章。隔夜是否并入日 RV，会改变 \\(\\beta_d\\) 与日历模式，见 <a href="/quant/calendar-overnight">日历效应与隔夜</a>。用开盘到收盘 RV 去预测收盘到收盘风险，左边右边不是同一对象。</p><p><span class="marginnote">RV 是方差。有人把 HAR 套在 \\(\\sqrt{RV}\\) 或 \\(\\log RV\\) 上，为了减轻右尾与异方差。对数 HAR 预测再指数化，存在 Jensen 调整。比较模型时须固定变换与损失，不能把对数域的 \\(R^2\\) 和水平域的 \\(R^2\\) 混排。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>估计。</strong> OLS 即可。残差有异方差与肥尾，标准误用 Heteroskedasticity-and-Autocorrelation-Consistent（HAC）。\\(\\beta_d,\\beta_w,\\beta_m\\) 通常皆正，和接近但小于 1，对应强持续但仍均值回复。若某市场 \\(\\beta_m\\) 接近零，月成分弱，可能是样本短或该资产没有慢波动层。</p><p><strong>扩展。</strong> 把跳跃稳健的连续变差与跳跃分开进 HAR（HAR-CJ）；加入隔夜收益平方；对多元用已实现协方差的 HAR。Corsi 原文也讨论 HAR 在模拟的长记忆数据上能逼近 ACF。实务上还可加杠杆项（昨日负收益）以吸收非对称，但这已滑向 EGARCH 的领土，应报告是否真改善样本外 QLIKE。</p><p><strong>与 GARCH 的分工。</strong> GARCH 用日收益平方当噪声极大的波动代理；HAR 用日内信息压缩后的 RV，信噪比高一个数量级。短样本里 HAR 的一日前预测通常打赢 GARCH(1,1)。GARCH 的优势是：没有高频数据时仍能给出 \\(\\sigma_t\\)，以及与收益方程联立。两者可以合成 <a href="/quant/realized-garch">已实现 GARCH</a>。</p><h3 id="带宽与网格先于-har-系数" tabindex="-1">带宽与网格先于 HAR 系数 <a class="header-anchor" href="#带宽与网格先于-har-系数" aria-label="Permalink to &quot;带宽与网格先于 HAR 系数&quot;">​</a></h3><p>垃圾 RV 进、垃圾预测出。五分钟 RV 在流动股票上可当工作马；tick 噪声大的标的应先核或预平均。HAR 的滞后是日历交易日，不是钟表 7×24；假期会让「5 日」实际跨更长日历，一般可忽略，但指数切换日应剔除或单独哑变量。不要在未清洗的成交价 RV 上解释 \\(\\beta_d\\) 特别大——那可能是微观噪声的短记忆，不是异质交易者。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>异质市场：短线交易者对日波动反应，中线对周，机构与公司决策对月。把三层成分相加，总体 ACF 下降得比 AR(1) 慢，看起来像长记忆。这是近似，不是估计了分整 \\(d\\)。机制的可检验含义是：不同期限的 RV 成分应对不同冲击敏感——例如宏观公告更多打月成分，盘中流动性更多打日成分。HAR 本身太粗，分不开这些，只是把持续分层写进线性方程。</p><p>预测机制是多步迭代或直接投影。迭代 HAR 把预测的 \\(RV_{t+1}\\) 填回周、月平均，再推 \\(t+2\\)；直接 HAR 用同一组滞后对 \\(RV_{t+h}\\) 再回归一次。多步时月成分权重上升，这是慢变量在长地平线上占优，不是参数不稳定。风控若关心一周 VaR，应看周地平线的直接投影，而不是只报告一日 \\(R^2\\)。</p><p><span class="marginnote">HAR 残差仍有波动的波动：大 RV 之后预测误差也大。这不影响 OLS 的一致性，但影响区间。要用预测当保证金，应对残差做 GARCH 或用分位回归，不能只拿条件均值当「明天的波动」。</span></p><h3 id="长记忆近似的边界" tabindex="-1">长记忆近似的边界 <a class="header-anchor" href="#长记忆近似的边界" aria-label="Permalink to &quot;长记忆近似的边界&quot;">​</a></h3><p>真分整在大滞后仍双曲线衰减；HAR 在滞后超过一个月后衰减受 \\(\\beta_m\\) 约束，更像高阶短记忆。对年度地平线，HAR 会过快回到无条件均值。Corsi 的主张是：交易与风控关心的预测地平线正是日到月，在这段上简约模型的样本外表现优于脆弱的 \\(d\\)。超过这个地平线，应换对象（例如宏观状态、期权期限结构），而不是把月平均改成年平均再叫 HAR。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>HAR 对 RV 定义敏感：是否含跳、是否含隔夜、采样网格、是否对数。横截面比较必须统一管道。结构突变（危机）会让全样本 \\(\\beta\\) 被高波动年主导；滚动 HAR 更适合实盘，但滚动窗太短则月成分估不稳。不要把 HAR 预测当成可交易的方差互换 alpha：还差风险溢价、跳跃补偿与执行。</p><p>计算极轻，适合全市场扫描。真正的工程成本在上游：清洗、网格、隔夜处理。下游若把 HAR 输出送进组合优化，注意 RV 预测与收益预测的频率对齐，以及个股 RV 加总并不等于组合 RV（还要相关）。多元 HAR 或对因子组合直接估 RV，通常比先对每个名字估再加总更干净。</p><p><span class="marginnote">QLIKE 对低估波动惩罚更重，和风控不对称一致。只报 MSE 会让模型靠压低高峰来讨好平方损失。波动预测的模型比较应至少同时给 QLIKE 与一种尾部分数。</span></p>',27)),(t(),l(d,null,{default:r(()=>[s(o,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20HF%5B%22%E6%97%A5%E5%86%85%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20RV%5B%22%E6%97%A5%20RV%20%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20RV%20--%3E%20D%5B%22%E6%98%A8%E6%97%A5%20RV_t%22%5D%0A%20%20RV%20--%3E%20W%5B%22%E5%91%A8%E5%B9%B3%E5%9D%87%20RV%22%5D%0A%20%20RV%20--%3E%20M%5B%22%E6%9C%88%E5%B9%B3%E5%9D%87%20RV%22%5D%0A%20%20D%20--%3E%20HAR%5B%22HAR%20%E7%BA%BF%E6%80%A7%E6%8A%95%E5%BD%B1%22%5D%0A%20%20W%20--%3E%20HAR%0A%20%20M%20--%3E%20HAR%0A%20%20HAR%20--%3E%20F%5B%22%E9%A2%84%E6%8A%A5%20RV_%7Bt%2B1%7D%22%5D%0A%20%20F%20--%3E%20Q%5B%22QLIKE%20%2F%20%E9%A3%8E%E6%8E%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Corsi（2009）用日、周、月 RV 的线性组合近似长记忆，避免估计分整阶数，是 RV 预测的工作马。</li><li>对象是已实现方差的条件均值；不包含方差风险溢价，也不能替代噪声修正后的 RV 构造。</li><li>与 GARCH 相比，HAR 利用日内信息，一日前预测通常更准；无高频时仍需 GARCH。</li><li>对数或开方变换、隔夜与跳跃拆分，都会改系数；比较须固定损失（含 QLIKE）。</li><li>地平线超过月后，HAR 的长记忆近似变差；更长的风险应换状态变量或期权期限结构。</li><li>出处：Corsi, <em>A Simple Approximate Long-Memory Model of Realized Volatility</em>, Journal of Financial Econometrics, 2009。</li></ul>',2))])}const C=i(p,[["render",h]]);export{u as __pageData,C as default};
